from pathlib import Path
import json, re
ROOT=Path(__file__).parent
QDIR=ROOT/'data'/'questionnaires'
QDIR.mkdir(parents=True,exist_ok=True)

def options(labels, values=None):
    values = values if values is not None else list(range(len(labels)))
    return [{'value':v,'label':s} for v,s in zip(values,labels)]
def q(id_, text, opts, *, scored=True, section=None, help_=None, qtype='single', required=True, **extra):
    d={'id':id_,'text':text,'type':qtype,'options':opts,'required':required,'scored':scored}
    if section: d['section']=section
    if help_: d['help']=help_
    d.update(extra)
    return d
def make(id_,title,category,respondent,instruction,source,questions,scoring,**extra):
    d={'id':id_,'title':title,'category':category,'respondent':respondent,'instruction':instruction,
       'source':source,'version':'1.0-source-import','questions':questions,'scoring':scoring,
       'license_review_required':extra.pop('license_review_required',False),**extra}
    (QDIR/f'{id_}.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    return d

